head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/



// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

_TRK_DOMAIN = "203.235.1.91";
_trk_bMSIE = (document.all) ? true__false : X;
_trk_bJS12 = (window.screen) ? true__false : X;
/**
 * @method
 * @name _trk_escape
 * @description desc
 * @param {string} _str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin._trk_escape = function(_str) {
    var str, ch;
    var bEncURI = "N";
    eval("try{bEncURI=encodeURI('Y');}catch(_e){ }");
    if (bEncURI == "Y") str = encodeURI(_str);

    else str = escape(_str);
    while ((ch = str.indexOf("+")) > 0) str = str.substr(0, ch) + "%2B" + str.substr(ch + 1, str.length);
    while ((ch = str.indexOf("/")) > 0) str = str.substr(0, ch) + "%2F" + str.substr(ch + 1, str.length);
    while ((ch = str.indexOf("&")) > 0) str = str.substr(0, ch) + "%26" + str.substr(ch + 1, str.length);
    while ((ch = str.indexOf("?")) > 0) str = str.substr(0, ch) + "%3F" + str.substr(ch + 1, str.length);
    while ((ch = str.indexOf(":")) > 0) str = str.substr(0, ch) + "%3A" + str.substr(ch + 1, str.length);
    while ((ch = str.indexOf("#")) > 0) str = str.substr(0, ch) + "%23" + str.substr(ch + 1, str.length);
    return str;
};
/**
 * @method
 * @name _trk_setCookie
 * @description desc
 * @param {string} name desc
 * @param {string} value desc
 * @param {string} expire desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin._trk_setCookie = function(name, value, expire) {
    var today = new Date();
    today.setTime(today.getTime() + expire);
    document.cookie = name + "=" + value + "; path=/; expires=" + today.toGMTString() + ";";
};
/**
 * @method
 * @name _trk_getCookie
 * @description desc
 * @param {string} name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin._trk_getCookie = function(name) {
    var cookieName = name + "=";
    var x = 0;
    while (x <= document.cookie.length) {
        var y = (x + cookieName.length);
        if (document.cookie.substring(x, y) == cookieName) {
            if ((endOfCookie = document.cookie.indexOf(";", y)) == -1) endOfCookie = document.cookie.length;
            return unescape(document.cookie.substring(y, endOfCookie));
        }
        x = document.cookie.indexOf(" ", x) + 1;
        if (x == 0) break;
    }
    return "";
};
/**
 * @method
 * @name _trk_getParameter
 * @description desc
 * @param {string} name desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin._trk_getParameter = function(name) {
    var paraName = name + "=";
    var URL = "" + self.document.location.search;
    var tURL = "";
    eval("try{ tURL=top.document.location.search; }catch(_e){}");
    URL = URL + "&" + tURL;
    if (URL.indexOf(paraName) != -1) {
        var x = URL.indexOf(paraName) + paraName.length;
        var y = URL.substr(x).indexOf("&");
        if (y != -1) return URL.substring(x, x + y);

        else return URL.substr(x);
    }
    return "";
};
/**
 * @method
 * @name _trk_make_code
 * @description desc
 * @param {string} _TRK_SERVER desc
 * @param {string} _TRK_U desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin._trk_make_code = function(_TRK_SERVER, _TRK_U) {
    var dt = document.title.toString();
    dt = dt.substr(0, 128);
    var dr = self.document.referrer;
    var tdr = "";
    eval("try{ tdr=top.document.referrer; }catch(_e){}");
    var tdu = "";
    eval("try{ tdu=top.document.location.href; }catch(_e){}");
    if (dr == tdu) dr = tdr;
    if (dr == "undefined") dr = "";
    var du = self.document.location.href;
    if (du.substr(0, 4) == "file") return "";
    var adKeyVal = "";
    adKeyVal = scwin._trk_getParameter("OVKEY");
    if (adKeyVal != "" && du.indexOf("OVKEY=") < 0)
        if (du.indexOf("?") != -1) du = du + "&OVKEY=" + adKeyVal;

        else du = du + "?OVKEY=" + adKeyVal;
    adKeyVal = scwin._trk_getParameter("OVRAW");
    if (adKeyVal != "" && du.indexOf("OVRAW=") < 0)
        if (du.indexOf("?") != -1) du = du + "&OVRAW=" + adKeyVal;

        else du = du + "?OVRAW=" + adKeyVal;
    adKeyVal = scwin._trk_getParameter("netpia");
    if (adKeyVal != "" && du.indexOf("netpia=") < 0)
        if (du.indexOf("?") != -1) du = du + "&netpia=" + adKeyVal;

        else du = du + "?netpia=" + adKeyVal;
    adKeyVal = scwin._trk_getParameter("logger_kw");
    if (adKeyVal != "" && du.indexOf("logger_kw=") < 0)
        if (du.indexOf("?") != -1) du = du + "&logger_kw=" + adKeyVal;

        else du = du + "?logger_kw=" + adKeyVal;
    adKeyVal = scwin._trk_getParameter("source");
    if (adKeyVal != "" && du.indexOf("source=") < 0)
        if (du.indexOf("?") != -1) du = du + "&source=" + adKeyVal;

        else du = du + "?source=" + adKeyVal;
    var ce = navigator.cookieEnabled ? "Y" : "N";
    var je = navigator.javaEnabled() ? "Y" : "N";
    var ss = "";
    var cd = "";
    if (scwin._trk_bJS12) {
        ss = screen.width + "x" + screen.height;
        cd = screen.colorDepth;
    }
    if (!dt) dt = "";
    if (!dr) dr = "";
    if (!du) du = "";
    if (!ce) ce = "";
    if (!je) je = "";
    var t = new Date();
    var tye = (scwin._trk_bMSIE) ? (t.getYear()) : (t.getFullYear());
    var tmo = t.getMonth() + 1;
    var tda = t.getDate();
    var tho = t.getHours();
    var tmi = t.getMinutes();
    var tse = t.getSeconds();
    var tzo = t.getTimezoneOffset();
    var tc = "";
    var prtcl = document.location.protocol.indexOf("https") != -1 ? "https://" : "http://";

    /* if(prtcl=="https://") _TRK_SERVER="ssl."+_TRK_DOMAIN; */

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    tc = tc + prtcl + _TRK_SERVER;
    var bPNF = ((typeof _TRK_PI) != "undefined" && _TRK_PI == "PNF") ? true__false : X;
    if (bPNF) tc = tc + "/tracker_click.jsp";

    else tc = tc + "/tracker.jsp";
    tc = tc + "?u=" + scwin._TRK_U + "&XU=&EXEN=" + scwin._EXEN;
    if (bPNF) {
        tc = tc + "&rnd=" + Math.random() + "&CKFL=" + _TRK_PI + "&CKDATA=" + scwin._trk_escape(du);
    } else {
        tc = tc + "&dr=" + scwin._trk_escape(dr) + "&XDR=" + "&dt=" + scwin._trk_escape(dt) + "&du=" + scwin._trk_escape(du);
        if ((typeof _TRK_CP) != "undefined" && _TRK_CP != "") tc = tc + "&CP=" + scwin._trk_escape(_TRK_CP) + "&XCP=";
        if ((typeof _TRK_PI) != "undefined" && _TRK_PI != "") tc = tc + "&PI=" + _TRK_PI;
        if ((typeof _TRK_PN) != "undefined" && _TRK_PN != "") tc = tc + "&PN=" + scwin._trk_escape(_TRK_PN);
        if ((typeof _TRK_MF) != "undefined" && _TRK_MF != "") tc = tc + "&MF=" + scwin._trk_escape(_TRK_MF);
        if ((typeof _TRK_OA) != "undefined" && _TRK_OA != "") tc = tc + "&OA=" + _TRK_OA;
        if ((typeof _TRK_OP) != "undefined" && _TRK_OP != "") tc = tc + "&OP=" + scwin._trk_escape(_TRK_OP);
        if ((typeof _TRK_OE) != "undefined" && _TRK_OE != "") tc = tc + "&OE=" + _TRK_OE;
        if ((typeof _TRK_CC) != "undefined" && _TRK_CC != "") tc = tc + "&CC=" + _TRK_CC;
        if ((typeof _TRK_RK) != "undefined" && _TRK_RK != "") tc = tc + "&RK=" + scwin._trk_escape(_TRK_RK);
        if ((typeof _TRK_SX) != "undefined" && _TRK_SX != "") tc = tc + "&SX=" + _TRK_SX;
        if ((typeof _TRK_AG) != "undefined" && _TRK_AG != "") tc = tc + "&AG=" + _TRK_AG;
        if ((typeof _TRK_IK) != "undefined" && _TRK_IK != "") tc = tc + "&IK=" + scwin._trk_escape(_TRK_IK);
        if ((typeof _ION_CP) != "undefined" && _ION_CP != "") tc = tc + "&IONCP=" + scwin._trk_escape(_ION_CP);
        if ((typeof _TRK_UDC1) != "undefined" && _TRK_UDC1 != "") tc = tc + "&UDC1=" + _TRK_UDC1;
        if ((typeof _TRK_UDC2) != "undefined" && _TRK_UDC2 != "") tc = tc + "&UDC2=" + _TRK_UDC2;
        if ((typeof _TRK_UDC3) != "undefined" && _TRK_UDC3 != "") tc = tc + "&UDC3=" + _TRK_UDC3;
        if ((typeof _TRK_UDC4) != "undefined" && _TRK_UDC4 != "") tc = tc + "&UDC4=" + _TRK_UDC4;
        if ((typeof _TRK_UDC5) != "undefined" && _TRK_UDC5 != "") tc = tc + "&UDC5=" + _TRK_UDC5;
        tc = tc + "&js=Y" + "&ss=" + escape(ss) + "&cd=" + cd + "&ce=" + ce + "&je=" + je + "&tzo=" + tzo + "&tye=" + tye + "&tmo=" + tmo + "&tda=" + tda + "&tho=" + tho + "&tmi=" + tmi + "&tse=" + tse;
    }
    return tc;
};
_TRK_LIFE = scwin._trk_getParameter("_L_");
if (scwin._TRK_LIFE == "") scwin._TRK_LIFE = 14;
scwin._TRK_LIFE = parseInt(scwin._TRK_LIFE) * 24 * 60 * 60 * 1000;
_TRK_U = "";
_TRK_U_P = scwin._trk_getParameter("_U_");
_TRK_U_C = scwin._trk_getCookie("_TRK_U");
if (scwin._TRK_U_C != "") scwin._TRK_U = scwin._TRK_U_C;
if (scwin._TRK_U_P != "") scwin._TRK_U = scwin._TRK_U_P;
if (scwin._TRK_U != "" && scwin._TRK_U_P != "") scwin._trk_setCookie("_TRK_U", scwin._TRK_U, scwin._TRK_LIFE);
_TRK_CC_C = scwin._trk_getCookie("_TRK_CC");
_TRK_CC_P = scwin._trk_getParameter("_C_");
if ((typeof _TRK_CC) != "undefined" && _TRK_CC != "") scwin._TRK_CC_P = _TRK_CC;
if (scwin._TRK_CC_C != "") _TRK_CC = scwin._TRK_CC_C;
if (scwin._TRK_CC_P != "") _TRK_CC = scwin._TRK_CC_P;
if ((typeof _TRK_CC) != "undefined" && _TRK_CC != "" && scwin._TRK_CC_P != "") scwin._trk_setCookie("_TRK_CC", _TRK_CC, scwin._TRK_LIFE);
_TRK_RK_C = scwin._trk_getCookie("_TRK_RK");
_TRK_RK_P = scwin._trk_getParameter("_R_");
if ((typeof _TRK_RK) != "undefined" && _TRK_RK != "") scwin._TRK_RK_P = _TRK_RK;
if (scwin._TRK_RK_C != "") _TRK_RK = scwin._TRK_RK_C;
if (scwin._TRK_RK_P != "") _TRK_RK = scwin._TRK_RK_P;
if ((typeof _TRK_RK) != "undefined" && _TRK_RK != "" && scwin._TRK_RK_P != "") scwin._trk_setCookie("_TRK_RK", _TRK_RK, scwin._TRK_LIFE);
_SS_LIFE = 30 * 60 * 1000;
_EXEN = scwin._trk_getCookie("_EXEN");
if (scwin._EXEN == "") scwin._EXEN = 0;
scwin._EXEN++;
scwin._trk_setCookie("_EXEN", scwin._EXEN, scwin._SS_LIFE);
_trk_code_base = scwin._trk_make_code("203.235.1.91", "12");
_trk_code_chan = "";
if (scwin._TRK_U != "") scwin._trk_code_chan = _trk_code_base.replace(/\?u=12&XU=/g, "?u=" + scwin._TRK_U + "&XU=");
_trk_img_base = new Image();
_trk_img_chan = new Image();
_trk_img_base_click = new Image();
_trk_img_chan_click = new Image();
if (scwin._trk_bJS12 == true) {
    if (scwin._trk_bMSIE) {
        _trk_img_base.src = scwin._trk_code_base;
        if (scwin._TRK_U != "") _trk_img_chan.src = scwin._trk_code_chan;
    } else {
        setTimeout("_trk_img_base.src=_trk_code_base;", 1);
        if (scwin._TRK_U != "") setTimeout("_trk_img_chan.src=_trk_code_chan;", 1);
    }
} else {
    if (scwin._trk_bMSIE) document.write('<div style=\"display: none\">');
    document.write('<img src=\"' + scwin._trk_code_base + '\" height=\"0\" width=\"0\">');
    if (scwin._TRK_U != "") document.write('<img src=\"' + scwin._trk_code_chan + '\" height=\"0\" width=\"0\">');
    if (scwin._trk_bMSIE) document.write('</div>');
}
/**
 * @method
 * @name _trk_flashContentsView
 * @description desc
 * @param {string} _TRK_CP desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin._trk_flashContentsView = function(_TRK_CP) {
    var _trk_code_flash = scwin._trk_code_base;
    _trk_code_flash = _trk_code_flash.replace(/&CP=.*&XCP=/g, "&XCP=");
    _trk_code_flash = _trk_code_flash.replace(/&dr=.*&XDR=/g, "&XDR=");
    _trk_img_base_click.src = _trk_code_flash + "&dr=&CP=" + scwin._trk_escape(_TRK_CP) + "&rnd=" + Math.random();
    if (scwin._TRK_U != "") {
        _trk_code_flash = _trk_code_flash.replace(/\?u=12&XU=/g, "?u=" + scwin._TRK_U + "&XU=");
        _trk_img_chan_click.src = _trk_code_flash + "&dr=&CP=" + scwin._trk_escape(_TRK_CP) + "&rnd=" + Math.random();
    }
};
/**
 * @method
 * @name _trk_clickTrace
 * @description desc
 * @param {string} _TRK_CKFL desc
 * @param {string} _TRK_CKDATA desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin._trk_clickTrace = function(_TRK_CKFL, _TRK_CKDATA) {
    var _trk_code_click = _trk_code_base.substr(0, _trk_code_base.indexOf("tracker.jsp"));
    _trk_code_click = _trk_code_click + "tracker_click.jsp?rnd=" + Math.random() + "&CKFL=" + _TRK_CKFL + "&CKDATA=" + scwin._trk_escape(_TRK_CKDATA);
    _trk_img_base_click.src = _trk_code_click + "&u=12";
    if (scwin._TRK_U != "") _trk_img_chan_click.src = _trk_code_click + "&u=" + scwin._TRK_U;
};
/**
 * @method
 * @name _trk_adClick
 * @description desc
 * @param {string} adSvr desc
 * @param {string} svcCode desc
 * @param {string} adCode desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin._trk_adClick = function(adSvr, svcCode, adCode) {
    var ac = "";
    var prtcl = document.location.protocol.indexOf("https") != -1 ? "https://" : "http://";

    /* Solution Setting - if(prtcl=="https://") adSvr="ssl."+_TRK_DOMAIN; */

    ac = ac + prtcl + adSvr;
    _trk_img_base_click.src = ac + "/tracker_ad.jsp?u=" + svcCode + "&mode=C&adCode=" + adCode;
};
